//! ♻️ Live callback closure preserves source while its original execution is fully retired.
use super::*;
use semio_framework_job::{StepContext,StepBudget,OperationId,Generation,root_cancel_token};
use std::cell::Cell;

/// 🪪️ Cancellation reaches the registered child only after paid execution cleanup under fixed copy.
#[test]
fn original_inference_gateway_closes_execution_before_same_child(){
 struct Child{source:usize,calls:Cell<usize>}
 fn cancel(request:&ArtifactInferenceExecutionRequest<'_>,context:&dyn std::any::Any)->Result<ArtifactInferenceExecutionStep,ArtifactInferenceExecutionError>{let child=context.downcast_ref::<Child>().unwrap();assert_eq!((request.operation,request.generation),(71,3));assert_eq!(request.canonical_payload.as_ptr()as usize,child.source);assert!(request.cancelled);child.calls.set(child.calls.get()+1);Ok(ArtifactInferenceExecutionStep{execution:None,retained_progress:item(),terminal:true})}
 fn demand(request:&ArtifactInferenceExecutionRequest<'_>,context:&dyn std::any::Any,_copy:usize)->Result<RetirementDemand,ValueError>{let child=context.downcast_ref::<Child>().unwrap();assert_eq!(request.canonical_payload.as_ptr()as usize,child.source);Ok(RetirementDemand{depth:1,..Default::default()})}
 let metadata=ArtifactInferenceServiceMetadata{owner:"test.gateway.close",artifact_kind:"test.gateway.close",artifact_schema:"test.gateway.close",artifact_schema_version:1,inference_schema:"test.gateway.close",inference_schema_version:1,algorithm_version:1,policy_version:1,payload:None};crate::app::register_artifact_inference_service(ArtifactInferenceService::new_contextual(metadata,cancel,demand)).unwrap();
 for copy in [1,3,64]{
  let raw=b"same original raw caller";let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};let request=WireArtifactInferenceRequest{wire_version:ARTIFACT_INFERENCE_WIRE_VERSION,owner:metadata.owner.into(),artifact_kind:metadata.artifact_kind.into(),artifact_schema:metadata.artifact_schema.into(),artifact_schema_version:1,inference_schema:metadata.inference_schema.into(),inference_schema_version:1,algorithm_version:1,policy_version:1,revision:11,generation:3,source_dialect:"same original dialect".into(),policy:b"same original policy".to_vec(),budgets:WireArtifactInferenceBudget{allocation_bytes:1048576,work_units:1,recursion_depth:128},retained:grant,cancellation_id:"same original cancellation".into(),previous_state:Some(b"same original checkpoint".to_vec()),requested_cache_mode:WireArtifactInferenceCacheMode::Cold,canonical_payload:b"same original payload".to_vec(),dependencies:vec![("same original dependency".into(),b"same dependency payload".to_vec())]};let child=Child{source:request.canonical_payload.as_ptr()as usize,calls:Cell::new(0)};
  let mut owner=ArtifactInferenceGateway::new(71,3,raw);owner.request=Some(request);owner.stage=3;owner.child_live=true;owner.discarded_execution=Some(ArtifactInferenceExecution{retirement_progress:Default::default(),canonical_payload:Some(b"same retained execution".to_vec()),diagnostics:Vec::new(),validity:"valid".into(),quality:"same original quality".into(),complete:false,actual_cache_mode:WireArtifactInferenceCacheMode::Cold});owner.begin_close();let mut sequence=0;let cancel=root_cancel_token();
  for turn in 0..100000{
   let(discarded,active,calls)=(owner.discarded_execution.is_some(),owner.active.is_some(),child.calls.get());let(quoted,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.retirement_demands_with_context(Some(&child),copy));let quote=quoted.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=RetainedCloneGrant{maximum_capacity_bytes:quote.capacity_bytes,maximum_release_bytes:quote.release_bytes,maximum_depth:quote.depth.max(1),..grant};let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,RetainedCloneGrant{maximum_items:0,..grant}),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(raw,&mut cx,Some(&child)));assert!(result.refusal.is_none()&&result.payload.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(cx);
   let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),&mut sequence,&mut receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(raw,&mut cx,Some(&child)));assert!(result.refusal.is_none()&&result.payload.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(result.retained_progress.retained_capacity_bytes,result.retained_progress.released_bytes));assert!(result.retained_progress.fits(grant));if discarded||(active&&calls==0){assert_eq!(child.calls.get(),0);}if let Some(request)=owner.request.as_ref(){assert_eq!(request.canonical_payload.as_ptr()as usize,child.source);}if owner.terminal_is_empty(){break}assert!(turn<99999,"original gateway close stalled copy={copy} live={} discarded={} active={}",owner.child_live,owner.discarded_execution.is_some(),owner.active.is_some());
  }
  assert_eq!(child.calls.get(),1);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Original gateway close copy={copy} executionFirst=true sameChildCancel=true sameSource=true actualSystemConservation=true Drop0=true");
 }
}
